import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Abood2D {

    static int N, fifty, hundred, K;
    static int memo[][][];
    static int memo2[][][][];
    static final int MOD = (int) 1e9 + 7;
    static long[][] comb;

    static int solve(int t, int f, int h) {
        if (f == 0 && h == 0)
            return 0;

        if (memo[t][f][h] != -1)
            return memo[t][f][h];

        if (t == 1)
            return 1 + (f < fifty ? solve(0, f + 1, h) : solve(0, f, h + 1));

        int ans = (int) 1e6;
        int maxF = Math.min(f, K / 50);
        for (int i = 0; i <= maxF; i++) {
            int maxJ = Math.min((K - i * 50) / 100, h);
            for (int j = 0; j <= maxJ; j++) {
                int totalW = i * 50 + j * 100;
                if ((fifty - f + i > 0 && totalW > 50) || (hundred - h + j > 1 && totalW > 100) || (i == fifty && j == hundred)) {
                    ans = Math.min(ans, solve(1, f - i, h - j));
                }
            }
        }
        return memo[t][f][h] = ans + 1;
    }

    static int solve2(int t, int f, int h, int r) {
        if (r == 0 && f == 0 && h == 0)
            return 1;
        if (r == 0)
            return 0;
        if (memo2[t][f][h][r] != -1)
            return memo2[t][f][h][r];

        long ans = 0;
        if (t == 1) {
            int maxI = Math.min(fifty - f, K / 50);
            for (int i = 0; i <= maxI; i++) {
                int maxJ = Math.min((K - i * 50) / 100, hundred - h);
                for (int j = 0; j <= maxJ; j++) {
                    if (i == 0 && j == 0)
                        continue;
                    long ways = (nCk(fifty - f, i) * nCk(hundred - h, j)) % MOD;
                    ans = (ans + ways * solve2(0, f + i, h + j, r - 1)) % MOD;
                }
            }
        } else {
            int maxI = Math.min(f, K / 50);
            for (int i = 0; i <= maxI; i++) {
                int maxJ = Math.min((K - i * 50) / 100, h);
                for (int j = 0; j <= maxJ; j++) {
                    if (i == 0 && j == 0)
                        continue;
                    long ways = (nCk(f, i) * nCk(h, j)) % MOD;
                    ans = (ans + ways * solve2(1, f - i, h - j, r - 1)) % MOD;
                }
            }
        }
        return memo2[t][f][h][r] = (int) ans;
    }

    static long nCk(int n, int k) {
        if (n < k)
            return 0;
        return comb[n][k];
    }

    static void initComb() {
        comb = new long[101][101];
        for (int n = 0; n <= 100; n++) {
            comb[n][0] = comb[n][n] = 1;
            for (int k = 1; k < n; k++) {
                comb[n][k] = (comb[n - 1][k - 1] + comb[n - 1][k]) % MOD;
            }
        }
    }

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        N = sc.nextInt();
        K = sc.nextInt();

        for (int i = 0; i < N; i++)
            if (sc.nextInt() == 50) fifty++; else hundred++;

        initComb();

        memo = new int[2][fifty + 1][hundred + 1];
        for (int i = 0; i < 2; i++)
            for (int j = 0; j <= fifty; j++)
                Arrays.fill(memo[i][j], -1);

        int min = solve(0, fifty, hundred);

        if (min >= (int) 1e6) {
            out.println(-1);
            out.println(0);
        } else {
            memo2 = new int[2][fifty + 1][hundred + 1][min + 1];
            for (int i = 0; i < 2; i++)
                for (int j = 0; j <= fifty; j++)
                    for (int j2 = 0; j2 <= hundred; j2++)
                        Arrays.fill(memo2[i][j][j2], -1);

            out.println(min);
            out.println(solve2(0, fifty, hundred, min));
        }

        out.flush();
    }

    static class Scanner {
        StringTokenizer st;
        BufferedReader br;

        public Scanner(InputStream s) { br = new BufferedReader(new InputStreamReader(s)); }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens())
                st = new StringTokenizer(br.readLine());
            return st.nextToken();
        }

        public int nextInt() throws IOException { return Integer.parseInt(next()); }
        public long nextLong() throws IOException { return Long.parseLong(next()); }
        public String nextLine() throws IOException { return br.readLine(); }

        public double nextDouble() throws IOException {
            String x = next();
            StringBuilder sb = new StringBuilder("0");
            double res = 0, f = 1;
            boolean dec = false, neg = false;
            int start = 0;
            if (x.charAt(0) == '-') {
                neg = true;
                start++;
            }
            for (int i = start; i < x.length(); i++)
                if (x.charAt(i) == '.') {
                    res = Long.parseLong(sb.toString());
                    sb = new StringBuilder("0");
                    dec = true;
                } else {
                    sb.append(x.charAt(i));
                    if (dec)
                        f *= 10;
                }
            res += Long.parseLong(sb.toString()) / f;
            return res * (neg ? -1 : 1);
        }

        public boolean ready() throws IOException { return br.ready(); }
    }
}
